package com.cursortrail;

import java.awt.Color;
import java.awt.event.MouseEvent;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayDeque;
import javax.inject.Inject;


import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.Point;
import net.runelite.api.events.ClientTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Cursor Trail",
	configName = "cursor_trail",
	description = "Adds a configurable cursor trail for visual clarity",
 enabledByDefault = true,
 tags = {"cursor", "ui", "trail", "clarity"},
 conflicts = {}
)
public class CursorTrailPlugin extends Plugin {
	private CursorTrailOverlay overlay;

	@Inject
	private Client client;

	@Inject
	private CursorTrailConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private MouseManager mouseManager;

	static class QueuedPoint {
		Instant when;
		Point where;
		Color color;

		public QueuedPoint(Instant when, Point where, Color color) {
			this.when = when;
			this.where = where;
			this.color = color;
		}
	}

	protected ArrayDeque<QueuedPoint> queue;
	public void queuePoint(MouseEvent event, boolean mouse) {
		Point position = client.getMouseCanvasPosition();

		Color color = this.config.base_color();
		MenuEntry[] entries = client.getMenu().getMenuEntries();
		MenuEntry entry = entries.length > 0 ? entries[entries.length - 1] : null;
		if(entry != null) {
			switch(entry.getType()) {
				case WALK:
				case CANCEL:
					break;
				default:
					color = this.config.hover_color();
					break;
			}
		}

		if(mouse) {
			color = this.config.drag_color();
		}

		this.queue.add(new QueuedPoint(Instant.now(), position, color));
	}

	private final MouseAdapter mouseAdapter = new MouseAdapter() {
		@Override
		public MouseEvent mouseMoved(MouseEvent event) {
			queuePoint(event, false);
			return event;
		}
		@Override
		public MouseEvent mouseDragged(MouseEvent event) {
			queuePoint(event, true);
			return event;
		}
	};

	@Override
	protected void startUp() throws Exception {
		this.queue = new ArrayDeque<>();

		if(overlay == null) {
			overlay = new CursorTrailOverlay(this, config);
		}
		overlayManager.add(overlay);
		mouseManager.registerMouseListener(mouseAdapter);
	}

	@Override
	protected void shutDown() throws Exception {
		this.queue = null;

		overlayManager.remove(overlay);
		mouseManager.unregisterMouseListener(mouseAdapter);
	}

	@Subscribe
	public void onClientTick(ClientTick event) {
		while(this.queue.peek() != null && Duration.between(this.queue.peek().when, Instant.now()).toMillis() > this.config.lifetime()) {
			this.queue.poll();
		}
	}

	@Provides
	CursorTrailConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(CursorTrailConfig.class);
	}
}

package com.cursortrail;

import java.awt.Color;


import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("cursor-trail")
public interface CursorTrailConfig extends Config {
	@ConfigItem(
			keyName = "width",
			name = "Width",
			description = "Width of the trail in px"
	)
	default double width() {
		return 1.0f;
	}

	@ConfigItem(
			keyName = "lifetime",
			name = "Lifetime",
			description = "How long to keep points in ms"
	)
	default int lifetime() {
		return 500;
	}

	@ConfigItem(
			keyName = "minimum",
			name = "Minimum",
			description = "Minumum distance between points"
	)
	default double minimum() {
		return 5.0f;
	}

	@ConfigItem(
			keyName = "base_color",
			name = "Base Color",
			description = "Color when not hovering or dragging"
	)
	default Color base_color() {
		return Color.GREEN;
	}

	@ConfigItem(
			keyName = "hover_color",
			name = "Hover Color",
			description = "Color while hovering an entity"
	)
	default Color hover_color() {
		return Color.YELLOW;
	}

	@ConfigItem(
			keyName = "drag_color",
			name = "Drag Color",
			description = "Color when dragging the mouse"
	)
	default Color drag_color() {
		return Color.RED;
	}
}

package com.cursortrail;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.geom.Line2D;
import java.util.Iterator;


import com.cursortrail.CursorTrailPlugin.QueuedPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class CursorTrailOverlay extends Overlay {
	private final CursorTrailPlugin plugin;
	private final CursorTrailConfig config;

	public CursorTrailOverlay(CursorTrailPlugin plugin, CursorTrailConfig config) {
		this.plugin = plugin;
		this.config = config;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPriority(1.0f);
	}

	@Override
	public Dimension render(Graphics2D graphics) {
		graphics.setStroke(new BasicStroke((float) this.config.width()));

		Iterator<QueuedPoint> points = this.plugin.queue.iterator();

		if(!points.hasNext()) {
			return null;
		}

		double minimum = 0.0F;
		double maximum = this.config.minimum();
		QueuedPoint last = points.next();
		while(points.hasNext()) {
			QueuedPoint point = points.next(); 
			if(point.where.distanceTo(last.where) < minimum) {
				continue;
			}

			Line2D.Double line = new Line2D.Double(last.where.getX(), last.where.getY(), point.where.getX(), point.where.getY());

			Color blend = new Color(
					(point.color.getRed() + last.color.getRed()) / 2,
					(point.color.getGreen() + last.color.getGreen()) / 2,
					(point.color.getBlue() + last.color.getBlue()) / 2,
					255);

			graphics.setColor(blend);
			graphics.draw(line);
			last = point;

			minimum = Math.min(maximum, minimum + 0.5f);
		}
		return null;
	}
}
